import type { Metadata } from "next";
import { GenericPage } from "@/components/sections/generic-page";
import { publicRoutes, routeTitles } from "@/lib/routes";

/** Routes that have their own page.tsx and must not be generated by the catch-all. */
const explicitRoutes = new Set([
  "naijashop",
  "search",
  "cart",
  "checkout",
  "orders",
  "wallet",
  "account",
  "naijaeats",
  "naijasend"
]);

export function generateStaticParams() {
  return publicRoutes.filter((slug) => !explicitRoutes.has(slug)).map((slug) => ({ slug }));
}

export function generateMetadata({ params }: { params: { slug: string } }): Metadata {
  const title = routeTitles[params.slug] ?? "NaijaDeals";
  return {
    title,
    description: `${title} on NaijaDeals.com.`
  };
}

export default function Page({ params }: { params: { slug: string } }) {
  return <GenericPage slug={params.slug} />;
}
